\u0061\u0060\u0060\u0055\u0052\u0053\u0074\u0022\u0054\u006d\u004e\u0042\u004b\u0021\u0079\u0079\u006e\u0073\u0079\u007a\u0057\u004a\u0021\u002f\u0044\u002f\u0065\u0057\u003d\u0073\u0032\u0027\u0029\u0034\u0061\u004e\u0032\u0050\u0053\u0025\u0074\u0051\u0071\u0051\u0025\u0022\u0049\u0030\u0041\u0074\u007e\u002c\u0039\u002d\u004f\u005c\u004f\u0029\u002f\u0021\u0039\u006f\u0023\u003c\u0076\u0049\u004b\u0075\u0021\u006b\u002f\u0034\u0032\u0065\u006c\u002a\u0071\u0072\u0029\u006f\u0059\u003d\u004f\u0041\u007b\u0072\u0078\u0071\u0044\u0055\u005b\u002a\u0021\u0036\u004c\u0035\u0052\u0035\u0079\u002b\u006e\u0033\u0028\u0074\u006b\u0054\u0062\u0039\u004e\u007e\u0076\u005b\u0065\u0051\u005e\u0071\u0066\u0051\u0069\u0062\u006a\u0057\u0056\u002f\u004b\u006d\u0045\u003d\u003a\u005f\u0044\u003f\u0067\u0031\u0022\u0025\u0066\u0026\u0065\u0050\u004f\u0070\u0058\u0030\u002c\u002c\u0067\u0051\u0071\u0029\u0051\u0053\u0028\u0051\u0060\u0061\u0038\u002e\u007b\u0027\u0021\u0063\u0079\u0070\u0037\u0055\u005c\u002d\u0029\u0054\u0030\u007a\u006d\u002f\u0076\u0022\u0032\u006a\u0020\u002f\u004c\u0050\u0033\u0075\u004b\u0072\u0066\u0061\u004e\u0060\u0020\u007a\u003b\u002d\u0064\u0048\u0072\u0079\u0062\u0045\u007a\u0053\u0049\u0020\u0062\u007e\u0043\u004f\u004c\u0063\u0072\u006f\u006b\u006c\u0061\u0070\u0079\u005e\u005b\u0025\u002b\u007b\u0023\u0036\u0068\u0076\u007d\u0031\u0041\u0065\u003e\u0078\u002c\u0048\u0063\u0053\u0050\u0032\u0066\u0029\u0044\u003f\u0061\u0045\u0075\u0077\u0041\u005f\u006e\u0069\u005a\u0071\u0042\u0065\u0072\u0053\u0050\u0049\u003f\u0023\u0039\u003e\u0056\u0032\u0040\u0046\u0051\u0036\u007d\u0063\u0066\u0020\u002b\u0070\u0065\u003c\u0042\u0078\u006c\u0066\u0050\u0031\u004e\u006a\u0040\u0074\u0020\u0036\u002b\u0037\u003c\u0049\u007e\u0037\u0054\u004a\u003e\u0067\u005c\u0044\u0062\u0056\u007e\u0049\u0029\u0065\u0067\u005b\u006a\u003c\u0033\u0026\u0078\u002f\u0028\u0073\u0070\u0048\u006f\u0020\u0034\u0020\u0037\u0025\u0034\u0060\u0075\u0058\u0060\u0058\u0034\u0023\u0034\u0054\u002d\u0041\u0067\u0046\u003e\u003c\u003b\u006a\u005c\u0062\u0021\u0059\u005f\u004b\u003e\u0022\u003f\u0071\u0072\u0066\u0079\u0064\u0072\u0039\u0072\u005b\u002d\u004a\u0074\u006d\u0063\u006d\u0037\u0025\u0058\u0042\u006a\u0076\u006d\u005b\u0024\u0064\u003d\u004d\u005c\u0058\u0046\u002e\u0051\u002b\u0048\u0043\u003e\u003d\u007a\u0049\u002f\u0068\u007e\u003d\u003f\u0044\u0027\u0030\u004c\u0063\u0023\u005d\u0073\u0061\u0040\u0072\u006f\u006a\u0046\u002a\u0071\u0021\u0071\u0064\u0065\u004a\u0035\u0046\u0078\u0048\u0062\u0065\u0045\u0035\u0068\u0065\u002c\u0051\u0041\u0050\u002d\u003d\u002a\u0032\u002e\u0052\u005f\u0027\u0063\u0028\u0050\u0035\u007c\u0042\u0047\u004e\u006b\u0055\u0059\u007b\u0060\u003d\u0040\u0055\u005f\u004f\u0041\u007c\u0031\u003b\u006e\u0072\u004e\u0042\u005a\u0032\u0072\u0032\u007e\u004b\u0078\u003b\u0066\u0021\u0021\u006e\u006b\u006b\u0029\u0063\u004c\u007b\u0073\u0079\u006d\u0052\u0025\u0034\u0024\u0025\u0073\u007b\u0028\u0032\u0056\u0056\u0079\u0077\u0020\u0049\u003c\u004a\u0034\u0063\u0078\u0052\u007e\u003f\u003c\u0074\u005a\u0033\u0075\u0064\u0021\u0055\u0069\u0061\u0029\u005c\u0042\u006a\u0074\u0043\u0078\u0074\u004c\u0039\u006e\u0066\u003f\u0031\u0077\u002c\u004e\u007d\u0068\u003d\u0040\u0069\u0034\u0065\u0059\u0061\u0022\u0075\u004e\u0069\u0041\u0062\u0032\u0030\u0051\u0074\u0031\u0065\u0062\u0031\u003a\u0075\u003e\u0059\u0058\u0058\u004d\u002a\u0037\u0032\u006f\u0024\u006b\u007a\u007a\u0078\u0053\u0051\u0051\u003b\u004a\u0057\u0023\u0066\u002e\u0041\u003d\u003f\u0052\u0059\u0054\u0049\u0046\u0059\u0062\u0033\u0025\u0033\u0045\u0023\u005e\u0048\u004a\u0078\u0064\u0055\u0052\u002b\u007d\u0041\u005b\u0025\u002e\u0064\u003e\u0027\u0053\u0036\u0057\u0065\u0043\u002d\u0052\u0063\u0055\u006e\u0037\u004a\u0044\u0026\u0078\u0060\u006a\u0025\u0034\u003e\u0052\u007b\u0069\u0047\u0078\u002c\u0059\u004f\u0076\u0067\u0038\u0072\u0074\u0022\u004c\u0065\u0072\u0056\u004b\u0020\u002f\u003a\u007c\u0027\u0061\u0058\u004d\u003a\u0073\u0049\u0053\u0074\u004d\u005f\u0060\u0078\u0065\u003d\u0039\u0037\u0021\u006d\u003e\u0037\u002d\u003d\u0071\u0054\u0041\u003b\u0034\u0050\u0037\u0063\u0023\u0042\u0042\u0054\u0075\u002c\u0074\u0020\u0024\u007e\u0078\u003f\u005f\u0021\u006e\u0029\u0071\u0061\u0045\u0053\u003c\u0063\u0060\u002b\u0020\u0073\u0065\u002a\u004a\u0070\u003d\u002a\u0029\u0060\u007b\u0053\u002d\u0040\u0032\u0029\u0027\u0031\u007b\u0049\u0049\u002d\u0035\u0036\u0069\u0042\u0023\u0041\u0057\u0052\u0024\u003f\u0045\u0067\u0049\u0047\u006a\u006f\u0035\u0064\u0050\u004b\u0039\u003b\u0058\u0023\u006d\u0072\u0036\u0068\u0043\u006e\u0079\u005f\u0074\u0033\u003f\u005f\u0051\u0053\u005b\u0079\u0069\u0030\u003c\u006f\u006d\u006b\u004a\u0032\u004e\u0029\u0048\u004a\u0028\u0066\u004c\u005f\u004d\u007d\u0044\u007c\u0059\u0045\u0035\u0071\u0075\u0027\u0060\u0063\u0055\u0032\u007b\u003d\u0047\u0051\u0036\u0068\u0021\u0071\u0026\u0027\u005b\u0070\u0061\u005f\u003d\u002e\u007b\u0037\u007e\u004f\u003f\u002a\u0040\u0065\u0039\u0049\u004e\u005a\u005a\u0069\u0022\u0042\u0060\u005d\u004d\u0026\u0065\u0064\u0049\u002b\u0029\u0049\u0035\u003a\u0034\u0053\u0044\u004c\u0077\u0075\u0077\u0036\u0027\u0050\u002e\u0020\u007c\u0045\u0029\u0045\u0055\u0022\u0062\u0056\u006e\u0032\u003e\u0077\u006d\u002f\u0020\u0033\u002d\u0021\u007d\u0070\u002d\u004c\u0067\u007e\u005a\u007c\u0052\u007b\u0056\u0034\u0026\u006c\u003e\u0021\u002b\u0070\u0029\u0063\u006a\u0030\u0074\u005d\u007c\u0075\u006e\u0042\u007d\u0033\u0030\u0040\u004b\u0025\u006c\u0037\u0069\u006b\u0075\u0074\u0066\u003c\u0070\u0071\u0023\u007c\u0071\u005d\u004a\u0060\u003f\u007b\u0049\u0022\u006f\u0049\u0076\u007b\u003c\u006b\u006a\u0068\u007e\u0070\u0061\u0069\u004f\u0061\u0030\u005b\u0049\u004d\u0056\u0022\u0025\u0024\u0068\u0044\u0027\u0031\u0075\u0028\u002d\u003f\u0055\u002a\u0059\u0068\u002d\u0067\u0037\u002e\u003f\u003b\u005b\u007e\u0078\u0040\u006f\u003c\u0052\u0066\u003a\u005e\u0048\u002f\u006e\u006e\u0068\u0060\u004c\u0063\u003c\u003f\u0059\u002b\u007c\u0023\u0076\u005f\u0071\u0054\u0063\u003c\u006e\u0038\u002e\u0028\u0022\u0067\u002d\u007a\u0027\u0052\u0070\u0070\u0025\u0065\u0033\u007c\u0055\u007a\u0043\u0060\u0077\u0065\u002c\u005e\u0066\u003b\u002c\u006b\u0076\u006d\u0025\u0067\u0069\u0050\u0028\u005d\u0033\u002c\u003e\u0032\u0050\u002e\u0036\u0033\u0024\u0074\u0065\u002a\u0052\u006b\u0068\u0040\u0028\u0028\u0079\u0051\u0033\u004b\u0028\u0078\u007c\u0028\u0035\u003c\u006d\u0070\u002e\u0076\u0025\u006f\u0033\u0075\u0063\u005c\u0055\u003b\u0059\u002d\u005f\u004a\u0047\u0063\u0054\u002f\u003d\u005f\u0052\u006d\u0039\u0064\u004b\u0059\u003e\u004b\u002c\u0032\u0077\u0063\u0066\u0042\u0044\u0036\u0054\u002c\u007c\u0071\u002b\u0067\u0031\u007a\u0020\u0067\u0032\u0038\u007b\u0047\u0050\u0070\u003f\u007a\u0058\u0028\u004f\u0046\u0073\u007b\u0043\u0022\u0064\u004d\u003c\u0055\u004d\u002d\u0058\u0059\u0046\u0067\u004b\u0056\u0034\u0077\u0031\u0035\u0028\u004f\u004b\u0020\u0066\u0057\u0073\u0049\u003e\u0068\u0058\u003d\u004b\u0072\u0043\u0076\u006b\u007d\u0043\u0028\u0020\u002e\u0039\u005f\u007a\u007c\u006d\u0074\u005d\u0067\u002b\u0050\u0079\u0029\u004a\u002b\u005a\u0067\u007d\u003f\u0042\u0051\u0046\u0062\u007a\u003e\u005b\u0023\u0048\u0031\u0030\u005d\u003d\u0054\u0071\u0074\u004c\u0059\u0071\u006d\u002c\u0028\u005d\u0037\u0074\u0021\u0035\u005a\u0057\u007d\u0021\u007b\u0044\u005f\u0047\u002a\u004b\u0054\u0038\u0069\u0020\u003e\u0030\u0074\u0038\u0058\u0044\u0052\u007d\u0041\u0067\u0078\u0048\u0034\u004f\u006c\u0029\u0060\u0077\u002b\u0025\u007c\u0077\u0024\u005b\u005b\u0020\u007a\u006f\u007e\u0051\u0045\u0059\u003e\u0020\u0026\u0048\u004e\u0071\u0038\u0022\u0044\u0073\u006e\u0065\u003a\u003b\u0063\u007e\u0069\u007d\u0024\u0031\u0073\u0052\u0038\u0059\u0029\u007b\u0054\u0043\u002c\u0075\u003c\u007e\u007e\u006c\u0031\u0058\u007a\u0038\u0041\u0052\u0025\u0023\u0048\u0023\u0072\u0073\u003f\u0062\u0062\u0043\u0070\u0039\u0047\u005e\u0032\u0038\u007b\u0055\u007c\u0020\u0066\u0036\u007a\u0041\u0056\u002f\u005a\u0068\u0041\u007d\u0049\u0054\u0068\u0076\u0058\u002f\u0059\u0060\u005b\u0049\u0046\u0059\u0074\u003e\u0052\u005c\u005d\u007a\u005f\u004c\u0075\u0046\u007e\u0020\u005c\u006c\u004e\u0079\u0078\u0057\u0066\u0030\u0058\u0052\u0057\u0072\u0071\u0079\u007b\u0067\u004a\u0031\u0072\u003d\u0075\u004b\u0042\u0030\u007b\u0048\u0029\u003a\u0027\u007a\u002b\u0056\u007c\u006c\u003c\u0051\u0044\u0053\u0072\u0063\u0042\u007e\u0067\u003f\u0037\u002c\u0025\u0062\u007d\u0042\u005e\u0068\u0020\u003f\u0021\u006f\u003c\u0050\u0044\u0070\u0037\u005e\u006a\u002a\u0064\u0020\u0049\u0066\u0063\u002e\u0037\u0066\u005c\u005c\u0044\u0037\u0056\u003d\u0030\u0022\u0037\u005f\u007b\u0038\u004b\u0071\u0057\u0075\u0031\u0079\u0031\u0050\u0077\u0076\u0038\u0052\u005d\u0051\u006a\u006d\u005d\u0021\u0021\u004e\u003a\u002a\u0065\u0044\u0057\u004e\u0056\u005a\u0076\u0060\u0049\u004d\u003c\u0046\u0031\u0037\u002e\u0040\u0028\u0051\u005a\u0047\u003a\u005d\u007a\u003c\u003f\u0039\u003f\u004e\u0047\u0073\u003e\u0062\u005e\u007e\u004d\u0050\u0068\u005b\u0039\u002d\u003d\u0053\u0051\u0079\u0056\u0060\u0063\u002c\u0059\u0069\u0063\u0069\u005c\u003b\u0057\u005a\u0046\u0048\u0031\u0066\u0033\u0021\u0052\u004d\u0065\u0024\u005f\u0049\u0064\u004a\u007a\u0058\u005b\u005f\u0023\u0059\u006f\u003c\u0079\u004b\u005c\u0061\u0026\u002a\u005d\u0040\u0054\u0023\u002b\u0045\u0038\u0024\u004e\u003d\u0053\u0020\u0021\u0055\u0051\u0051\u002b\u0039\u002c\u0077\u006c\u0038\u0065\u0020\u003c\u0027\u0020\u0026\u0076\u0059\u003b\u0077\u006a\u0062\u002a\u005d\u005e\u002c\u006d\u0050\u0028\u0041\u004a\u0054\u0038\u0029\u006a\u006b\u0071\u004c\u0040\u0041\u0069\u0037\u002d\u0041\u0073\u002f\u0026\u003c\u004c\u006d\u005b\u0027\u0046\u0038\u0021\u0055\u0079\u002f\u0020\u0043\u0047\u004b\u0077\u006c\u003b\u004b\u0057\u007c\u003a\u007b\u005b\u004a\u005e\u0033\u0058\u0020\u0072\u006a\u0029\u006c\u0031\u005b\u002f\u0032\u0042\u007a\u002f\u003e\u005c\u0021\u007a\u0030\u007e\u004a\u004d\u0044\u003a\u0043\u007c\u0036\u007c\u0044\u0020\u0021\u007c\u007d\u0072\u0062\u0069\u0060\u003b\u006b\u003f\u005f\u0049\u0077\u0020\u0061\u0063\u0061\u0042\u0058\u0064\u003d\u0069\u0042\u0079\u0035\u006c\u0020\u0041\u006b\u0022\u0051\u006d\u0052\u0066\u0079\u0047\u0020\u0022\u0026\u0031\u0034\u0061\u0076\u0041\u003d\u0039\u0072\u004d\u0056\u005e\u0061\u0054\u007c\u006b\u0050\u006e\u003c\u0043\u0042\u0049\u0033\u0076\u006b\u007b\u0023\u0048\u0068\u006a\u006e\u0054\u004f\u005c\u0049\u0066\u003e\u0075\u0057\u0023\u003e\u005a\u0027\u007a\u002d\u002c\u0029\u0027\u002e\u0068\u0025\u0063\u002d\u0044\u0068\u002a\u0023\u0065\u0036\u006d\u004f\u0022\u0024\u0025\u005f\u0049\u002a\u0028\u002b\u0023\u0077\u0073\u004d\u006f\u0066\u0067\u002b\u0079\u0032\u005d\u0052\u0071\u0038\u003a\u0077\u004b\u007b\u0062\u0064\u003c\u0025\u0028\u0077\u005b\u0043\u004d\u0037\u0058\u0073\u0048\u002d\u0045\u004e\u0037\u006a\u0076\u0043\u005a\u004e\u0056\u0057\u0047\u0057\u0021\u0078\u0030\u005e\u0026\u006b\u0049\u0041\u0021\u0029\u002e\u0045\u0071\u0074\u002c\u0047\u004f\u002a\u0037\u0036\u004b\u002c\u007b\u0050\u005c\u002e\u002f\u003e\u0030\u0020\u0044\u006d\u0028\u002c\u0037\u0074\u007e\u002c\u0036\u004e\u0050\u0024\u0072\u0038\u006f\u006d\u006a\u007e\u0046\u0043\u0035\u005c\u0072\u0064\u0045\u0056\u0077\u0021\u0040\u0029\u005d\u005a\u0027\u003f\u0067\u0063\u0050\u0052\u004d\u0061\u004b\u0034\u007a\u002e\u004c\u006d\u006b\u0056\u007b\u0023\u0046\u0071\u0028\u002f\u0057\u0074\u0047\u0046\u0031\u006c\u003d\u0045\u002b\u0046\u004c\u0024\u002d\u0021\u0045\u0071\u005a\u0027\u0059\u005d\u0066\u0065\u003b\u0042\u0045\u0038\u003f\u003c\u004c\u007a\u0028\u0057\u0031\u007a\u0040\u0027\u0041\u002b\u0035\u0036\u0077\u0037\u005d\u006b\u003c\u005f\u0062\u006b\u006f\u0072\u0032\u005d\u0049\u0074\u0072\u005a\u006a\u0062\u0065\u0046\u0076\u0027\u0078\u0025\u0050\u0035\u0036\u0037\u007b\u0024\u0029\u0030\u0022\u002e\u007a\u005e\u002b\u0045\u0069\u0067\u006c\u0056\u003f\u0047\u0060\u0035\u002c\u006a\u005c\u0052\u007d\u0037\u0045\u005e\u003c\u004a\u007e\u004b\u004e\u0074\u0065\u0023\u0049\u0071\u0063\u006e\u0061\u003c\u006b\u005e\u005c\u0031\u007c\u005a\u0069\u0036\u0024\u0022\u004b\u0035\u002a\u0021\u0050\u007a\u003c\u004b\u0034\u0030\u006a\u0055\u0055\u0075\u007d\u0028\u005c\u002f\u005c\u0058\u0038\u0045\u0078\u0053\u0062\u002a\u0059\u0073\u0038\u002c\u006e\u006d\u0039\u0060\u006c\u0075\u0042\u0048\u005f\u004e\u0031\u0024\u0036\u0071\u0065\u0028\u005c\u005c\u0047\u0061\u0060\u006f\u0026\u002c\u005f\u0079\u0020\u004f\u007c\u006f\u005c\u0026\u005d\u007e\u0055\u0054\u0051\u005e\u007e\u006b\u0043\u006a\u0067\u0073\u006b\u0073\u006a\u0052\u005a\u0074\u004b\u0060\u004e\u006f\u0035\u0079\u0027\u0043\u005c\u006d\u0072\u006a\u004d\u0048\u0061\u0041\u0027\u0038\u0057\u0042\u0023\u007e\u0070\u002d\u0021\u0027\u0061\u004e\u0039\u003b\u0058\u0078\u005a\u002c\u006c\u0058\u0023\u0021\u0068\u0046\u007c\u006b\u0032\u0074\u005d\u0042\u0050\u0072\u0057\u003b\u0047\u0054\u0025\u0049\u0047\u002c\u0053\u002d\u003d\u0062\u007c\u003d\u0031\u007a\u0053\u002f\u0076\u0024\u0025\u004e\u0051\u005b\u005b\u002c\u006f\u0034\u004e\u003a\u003d\u004d\u0042\u004a\u0051\u0076\u0038\u007a\u0075\u0037\u002d\u006c\u0063\u003a\u003d\u0064\u0074\u0072\u0054\u0020\u0028\u0025\u0042\u0073\u002f\u003e\u0079\u0076\u0065\u0035\u0053\u002f\u0042\u006f\u0033\u0073\u004d\u003e\u0037\u0027\u002b\u0075\u003f\u0020\u0041\u0024\u002b\u0068\u0074\u0059\u006f\u0039\u0077\u0025\u0056\u003b\u0055\u003c\u004a\u007e\u0055\u0045\u0052\u0073\u005c\u0056\u0037\u0067\u002a\u0021\u0063\u006c\u006e\u006e\u0041\u0027\u003d\u007c\u0043\u0052\u005e\u005f\u0074\u005b\u007c\u002f\u0076\u0026\u0026\u0025\u0025\u006b\u0051\u002c\u0058\u0065\u005c\u003b\u006a\u0033\u0049\u0026\u006b\u005c\u002c\u0025\u0036\u003e\u0022\u0026\u0054\u007c\u0077\u003a\u0077\u0038\u0024\u0049\u004a\u0057\u0055\u006a\u0034\u0075\u003e\u0065\u0077\u003e\u0057\u0053\u0042\u0032\u0045\u0043\u0066\u0076\u0050\u003c\u0072\u0048\u007e\u002b\u0042\u005b\u002d\u007c\u003a\u0038\u0020\u006e\u0069\u0074\u0066\u0053\u006b\u005f\u0026\u0070\u0057\u0038\u0027\u0061\u003e\u003f\u0074\u002b\u0046\u006c\u0036\u0074\u0063\u0064\u0054\u0050\u005b\u0076\u004f\u0026\u0071\u006a\u0040\u006b\u0078\u003c\u0046\u006b\u0023\u006d\u003e\u0062\u0060\u006f\u0032\u0072\u007d\u005d\u0043\u0027\u0064\u0070\u006a\u0058\u0034\u0064\u002b\u0058\u0059\u0032\u0032\u005a\u005a\u0038\u0045\u0054\u004d\u0021\u0042\u0021\u0034\u007e\u0041\u0041\u004e\u002c\u0050\u007a\u0033\u0052\u0062\u0076\u006c\u004e\u0076\u002d\u0073\u0035\u003a\u007e\u0061\u002b\u005d\u002d\u0070\u0040\u0067\u0073\u002a\u002a\u0023\u0035\u003c\u0061\u0031\u0044\u0025\u007c\u0079\u0067\u0079\u006c\u0037\u006d\u003e\u005d\u0077\u006a\u0063\u0067\u0078\u0052\u005f\u0043\u0042\u0070\u0037\u005e\u006c\u0060\u004a\u003d\u004f\u0065\u0060\u006d\u0037\u004d\u005a\u0048\u0041\u003b\u002e\u0052\u006d\u0071\u0057\u0054\u0047\u002f\u0031\u006e\u0029\u006b\u004f\u0076\u005b\u0050\u0062\u004b\u0022\u003a\u004b\u0020\u0062\u0073\u0038\u0030\u0060\u0050\u003e\u0067\u0055\u0042\u0053\u0036\u0048\u004d\u0068\u0051\u0057\u004b\u004d\u0046\u0027\u0021\u0054\u0051\u0068\u007d\u006b\u005a\u0071\u0033\u0069\u0073\u002b\u0033\u003b\u004f\u0032\u005e\u005b\u0038\u007e\u0035\u0061\u003b\u0048\u0067\u0044\u0048\u006b\u0033\u0022\u007b\u0054\u006b\u006f\u004f\u002b\u004e\u005d\u0063\u0067\u0060\u0056\u004e\u0078\u0060\u0077\u0064\u003e\u003b\u003e\u0037\u0031\u0065\u0072\u004a\u0039\u0049\u0066\u007c\u0045\u0021\u003a\u004b\u0029\u0045\u0064\u006a\u0061\u0056\u0030\u004d\u0045\u0036\u0058\u0050\u0033\u0023\u0063\u006f\u0036\u0047\u005b\u003f\u0061\u0077\u0055\u006e\u0049\u004c\u0039\u0030\u007a\u002a\u0057\u002b\u0071\u005b\u0062\u0067\u006d\u003e\u0077\u0026\u0036\u0034\u0044\u0059\u003c\u0035\u0063\u006d\u005f\u0028\u002d\u0047\u0047\u004f\u007d\u0048\u007a\u0063\u0044\u0038\u005d\u006f\u0074\u005c\u0059\u0024\u0061\u0062\u0062\u0055\u0035\u0030\u003d\u0070\u0066\u004e\u0027\u004b\u004e\u007e\u007a\u005c\u0042\u003b\u003b\u0064\u0066\u0026\u0034\u0034\u0032\u0070\u0032\u003d\u0039\u0066\u0058\u0032\u0070\u0073\u0032\u0020\u0058\u0051\u006b\u0078\u0032\u005b\u006f\u003e\u0057\u007c\u0047\u0063\u0064\u0022\u003f\u0064\u0062\u005e\u004e\u0075\u0067\u0072\u006a\u0029\u0028\u0049\u003a\u002c\u006f\u0030\u0051\u0067\u0045\u0032\u0048\u007c\u004a\u0026\u0031\u004f\u006f\u003e\u0055\u0074\u0078\u002e\u004e\u0067\u002c\u005d\u0038\u0077\u003f\u0055\u003d\u0032\u0024\u0043\u0026\u005f\u002c\u0044\u0033\u0025\u0055\u007c\u007b\u006f\u0029\u005a\u0061\u0053\u005e\u007d\u002c\u0023\u0071\u0052\u004b\u0060\u0036\u0064\u005a\u0077\u0057\u0023\u0039\u0074\u005c\u0067\u0022\u004a\u0021\u002d\u0044\u003c\u0031\u0035\u0065\u0061\u0029\u004c\u002f\u0032\u0048\u007b\u003d\u0076\u005e\u0041\u002e\u0071\u005c\u0027\u0030\u0033\u0071\u0048\u003e\u007b\u0027\u002c\u002d\u0075\u006e\u007e\u0048\u0047\u0072\u0036\u0032\u0072\u0021\u004e\u004c\u007e\u0031\u007e\u002a\u007c\u002c\u003f\u0036\u003a\u0039\u0036\u005a\u0058\u002c\u003b\u0062\u0029\u004c\u005d\u0045\u0078\u0062\u0024\u0061\u0053\u0063\u006e\u0023\u0030\u0020\u0059\u007b\u005c\u0049\u0040\u006e\u005b\u0032\u0058\u0069\u0023\u0038\u003d\u0043\u0078\u0023\u006d\u006c\u003b\u0075\u0059\u0057\u0024\u0022\u0060\u0052\u0068\u0029\u0022\u0040\u003d\u002b\u0075\u006e\u006d\u0056\u006d\u0033\u0020\u006a\u002e\u0072\u004a\u003f\u0057\u0027\u003a\u002e\u0033\u0021\u0056\u0034\u0028\u003d\u0036\u0037\u0046\u006a\u003e\u003a\u0034\u0056\u007a\u0052\u005b\u0046\u0054\u0043\u004b\u002c\u0063\u0075\u0037\u0057\u006d\u005d\u0052\u007d\u0066\u002b\u0060\u0051\u003d\u002c\u0024\u0021\u0058\u0033\u0058\u0036\u0022\u0055\u004e\u002c\u007a\u0030\u003c\u004b\u0041\u004a\u0035\u0036\u0042\u0070\u0055\u006f\u0037\u0030\u0058\u003c\u0054\u0041\u0063\u0045\u005f\u0042\u005f\u0039\u003d\u002e\u0047\u0071\u005b\u005b\u005c\u006c\u0043\u0064\u0075\u0040\u0028\u0049\u0030\u006d\u006d\u004d\u0022\u0029\u0079\u0053\u007c\u005c\u0024\u002f\u0059\u0020\u0066\u0067\u002b\u0052\u0031\u0028\u0047\u0038\u0028\u0059\u0076\u007d\u002b\u002d\u004e\u004d\u0036\u002a\u0034\u0040\u005c\u003a\u006c\u0068\u0035\u006b\u003d\u0079\u0070\u003b\u006f\u0057\u0077\u0061\u0034\u0026\u007a\u006b\u004f\u007b\u003b\u0041\u0050\u0052\u0043\u005c\u0058\u0053\u0061\u0067\u0023\u0025\u0068\u007b\u0048\u0039\u0069\u007c\u0074\u0074\u003f\u0030\u0058\u0052\u0036\u0070\u0028\u0067\u0062\u0020\u002a\u007a\u006a\u0054\u0036\u0045\u0038\u0069\u006f\u004d\u0037\u0076\u0057\u0024\u0069\u0029\u0030\u0065\u0049\u002b\u0055\u006b\u0075\u0064\u0079\u0038\u0072\u0057\u0029\u0032\u004b\u0068\u006e\u0035\u0040\u0041\u0057\u0057\u0042\u004d\u0077\u0042\u003d\u0040\u007a\u0079\u0044\u0079\u0046\u003b\u0061\u005d\u005f\u005d\u0042\u0062\u0031\u0067\u003a\u0040\u0057\u007d\u0069\u0051\u0043\u0049\u0071\u0023\u006f\u0033\u0043\u0029\u0035\u0073\u0026\u006c\u007c\u007d\u005c\u0025\u0054\u0077\u0049\u005f\u0064\u0060\u002e\u003a\u0048\u0021\u007e\u006a\u0044\u0033\u0062\u0044\u007a\u0064\u007b\u002d\u003d\u0051\u003f\u004c\u0047\u0076\u002a\u006d\u0056\u0054\u0060\u006b\u0034\u006c\u007c\u002d\u004c\u0033\u0023\u0065\u0040\u005d\u0064\u003e\u004a\u0035\u0034\u007e\u002d\u003f\u0039\u0040\u004d\u0020\u0030\u003b\u005c\u0064\u0045\u0031\u0036\u0075\u005b\u0054\u003e\u0063\u0073\u003c\u0053\u0078\u003b\u0053\u007b\u007d\u007c\u0064\u0038\u002d\u0037\u0062\u0048\u0039\u003c\u0066\u003c\u0054\u006c\u006e\u0067\u006f\u005b\u0066\u0049\u0060\u0066\u006a\u0063\u0071\u0063\u0047\u0053\u0060\u004b\u0038\u0072\u0034\u0049\u0045\u006b\u0071\u0056\u006e\u0078\u0050\u007d\u0073\u004e\u0025\u0049\u0076\u003f\u0075\u002e\u003d\u0048\u0031\u0041\u003e\u005d\u0067\u005c\u002c\u0077\u0025\u0062\u005f\u004e\u0076\u006a\u005a\u0037\u0048\u007e\u005a\u0028\u0064\u0076\u003e\u0046\u0068\u0056\u0043\u006e\u0046\u003e\u0028\u0020\u0073\u002f\u005d\u0078\u0076\u0059\u003b\u0044\u0030\u0023\u0027\u0045\u005d\u0044\u002e\u003f\u006a\u0039\u005a\u0059\u0063\u0057\u0024\u007d\u0079\u0050\u005e\u0077\u0046\u0049\u006a\u004d\u006f\u006b\u0027\u0031\u002d\u005c\u0051\u0068\u0073\u0049\u0070\u0066\u0074\u0053\u0048\u003f\u0062\u006e\u0023\u0076\u0072\u0029\u002e\u003d\u0045\u004b\u005c\u0035\u0057\u004b\u002e\u003c\u0048\u0065\u005e\u005c\u0050\u005b\u005d\u0024\u003e\u004b\u0078\u0078\u0026\u0042\u005d\u0056\u0055\u004d\u0054\u004c\u0055\u0057\u0036\u006d\u005e\u0046\u0020\u0077\u007b\u005d\u0024\u002c\u0038\u0026\u007a\u004d\u005f\u0035\u0065\u005d\u004d\u0021\u0051\u002c\u0070\u002d\u0054\u0030\u0063\u002e\u0057\u0071\u004a\u0047\u0025\u0045\u0053\u002e\u0025\u0075\u0045\u0045\u0026\u0075\u0066\u0041\u004c\u0079\u0042\u0040\u0026\u0072\u0050\u0070\u005c\u002e\u0031\u0020\u004b\u0053\u004d\u0065\u0051\u0065\u0048\u0065\u006a\u0048\u0045\u0027\u0034\u0068\u004f\u0056\u0055\u0047\u0077\u0053\u0055\u0053\u0032\u005e\u002e\u0041\u0061\u007b\u0025\u005b\u005e\u0060\u0054\u0060\u004f\u0070\u0076\u0031\u0065\u002b\u0053\u0055\u007c\u0077\u0041\u0074\u005a\u0046\u0044\u0025\u0053\u0026\u004b\u002e\u007b\u006d\u004e\u0077\u0074\u0070\u004e\u0068\u003d\u004f\u0038\u0063\u002a\u003f\u0071\u0079\u002e\u0038\u007d\u0072\u0022\u002c\u0061\u004c\u003e\u003a\u005e\u0049\u0050\u0026\u003b\u006f\u0020\u0063\u003f\u0075\u004a\u0053\u0068\u0023\u0029\u003d\u002c\u0037\u0048\u004f\u0020\u0072\u005b\u0030\u006b\u0021\u0032\u0027\u0059\u002d\u0074\u0064\u0062\u005a\u0072\u0039\u0050\u0064\u005b\u0028\u004d\u0023\u005d\u007d\u002f\u0057\u0079\u0043\u0069\u0047\u0027\u0038\u0071\u0063\u007b\u0049\u0042\u0039\u0038\u0035\u007d\u0034\u0046\u006f\u002c\u0054\u0058\u0079\u007a\u004a\u007d\u0064\u007d\u0026\u0054\u0043\u006f\u0053\u0022\u006a\u003c\u0042\u0064\u003f\u0056\u0073\u0062\u0020\u0046\u0042\u004c\u007c\u0072\u005f\u0079\u003b\u003c\u0072\u0021\u002a\u006a\u0025\u0042\u0040\u0069\u0054\u006c\u0043\u002e\u006a\u0036\u0064\u0042\u003a\u0078\u002d\u002b\u006c\u0033\u0021\u006c\u003f\u0038\u0054\u0068\u0077\u0028\u0049\u0032\u002e\u005e\u0037\u002c\u0067\u0048\u004a\u0022\u0048\u003e\u006b\u005f\u0033\u002a\u0063\u0035\u003b\u007a\u007d\u0021\u0057\u002c\u002a\u004d\u006e\u0036\u004b\u0021\u004f\u004f\u0021\u0059\u005c\u0048\u0050\u005f\u0070\u006d\u0058\u005d\u0052\u004b\u006b\u0032\u0075\u003d\u0047\u0071\u0030\u005a\u005e\u005f\u002c\u0028\u0049\u0027\u0060\u0053\u004b\u0075\u0073\u0025\u0027\u004b\u0054\u0073\u0072\u0036\u0031\u0041\u0045\u0052\u007a\u0027\u0041\u0070\u0024\u0052\u0060\u006c\u0038\u002b\u0030\u0055\u006d\u006e\u004c\u005e\u0070\u0035\u0049\u0074\u0054\u004f\u0075\u0060\u006c\u0020\u0034\u0073\u0043\u006e\u003e\u002e\u0068\u002a\u005a\u005d\u0067\u0035\u0062\u005c\u0030\u0032\u002f\u0071\u0022\u005f\u0038\u005e\u006b\u0073\u007e\u0020\u0078\u002e\u0065\u0054\u0070\u0075\u0066\u0043\u0040\u004c\u0047\u0058\u0030\u0024\u0067\u004b\u0043\u0044\u005f\u0036\u0034\u0047\u0067\u0033\u006a\u0078\u004d\u0065\u003d\u003c\u0062\u0060\u0057\u0046\u0078\u0024\u0050\u0028\u0042\u0062\u0034\u0041\u004f\u0048\u0039\u0064\u007c\u0028\u0041\u0071\u0073\u0041\u0042\u0038\u0024\u0035\u004b\u002e\u006a\u003e\u0036\u004f\u0069\u0057\u0034\u0079\u0071\u0049\u0076\u0022\u006c\u0050\u0044\u0044\u003d\u0075\u0024\u0063\u0024\u007e\u002d\u004e\u0033\u0064\u006a\u0070\u0059\u0067\u0032\u0068\u007d\u0066\u003a\u0021\u007d\u0023\u0042\u0066\u0057\u0031\u004a\u0028\u0059\u0050\u0055\u004f\u0067\u006b\u007d\u002c\u0077\u0065\u002a\u0021\u0024\u0026\u0038\u006d\u0055\u006c\u0061\u004c\u0039\u0024\u0061\u005e\u0070\u0024\u005c\u0051\u006e\u005f\u0023\u005e\u003e\u003c\u0022\u0059\u004a\u0067\u0053\u0032\u0043\u0054\u004e\u0026\u003a\u005d\u0069\u0037\u0047\u0074\u002b\u007e\u0057\u0037\u0071\u006e\u005d\u0062\u0021\u0047\u0021\u006a\u007a\u0022\u0030\u0035\u0044\u0061\u005d\u0037\u0055\u0026\u0057\u0039\u0032\u0057\u002c\u0047\u002b\u0077\u007b\u004f\u003e\u0037\u002b\u0079\u0055\u007b\u002f\u0037\u0053\u0037\u0032\u0078\u003f\u006e\u0040\u0051\u0074\u0042\u0078\u0045\u0039\u0075\u007c\u007d\u006d\u0031\u0041\u005c\u002b\u0027\u0037\u002e\u0074\u002d\u004e\u0036\u003e\u0078\u002c\u003e\u0070\u0068\u005e\u0049\u004d\u006d\u004a\u0054\u0055\u005e\u005d\u0048\u0022\u0020\u007e\u0038\u0046\u0033\u0076\u0076\u0063\u0026\u0021\u0049\u003a\u004d\u0076\u007c\u0073\u006f\u0037\u007c\u0057\u002e\u0071\u0057\u0042\u0053\u0061\u0050\u007e\u0070\u005e\u0074\u005a\u003a\u007d\u0047\u0076\u0050\u0032\u002a\u002e\u006a\u007c\u0030\u003f\u005c\u0042\u003a\u002b\u007d\u0064\u005c\u007b\u003c\u0041\u0067\u003b\u0035\u0073\u005d\u0025\u0052\u0043\u0053\u0061\u005c\u0064\u0056\u005d\u007e\u0067\u0023\u002c\u004d\u004e\u0070\u004b\u0034\u0035\u0028\u0029\u0068\u0036\u003c\u0071\u0033\u003d\u002e\u0052\u0039\u002d\u005f\u0066\u0050\u006d\u0054\u0042\u005d\u0076\u003e\u0064\u006f\u007e\u0061\u0043\u0042\u0058\u0057\u0072\u0028\u007d\u0053\u0036\u0037\u004e\u0061\u0044\u003d\u002f\u006e\u0020\u002d\u0071\u0061\u006d\u0038\u0027\u004f\u005a\u0056\u0034\u0059\u0063\u0055\u0048\u006f\u006d\u006e\u0076\u0077\u0051\u005d\u003d\u006e\u0039\u003d\u004f\u0040\u0048\u0045\u003d\u006c\u005b\u0057\u0040\u0063\u003f\u0064\u0024\u0042\u0046\u0050\u0068\u0064\u006b\u002c\u0049\u0068\u0047\u0050\u002e\u0055\u0036\u0039\u0045\u002a\u0051\u0033\u005e\u0072\u006e\u007d\u003b\u006c\u0076\u006e\u0058\u0039\u0047\u0061\u005c\u003d\u0022\u0038\u0059\u0039\u004e\u0037\u0025\u007e\u0036\u0048\u0075\u0024\u0030\u0054\u0068\u0056\u002b\u002d\u005b\u0062\u0065\u0051\u0057\u0059\u002a\u0025\u007a\u0038\u0025\u0040\u004b\u0067\u0027\u002a\u006d\u002a\u0056\u0041\u002b\u0053\u0069\u0049\u002a\u005a\u0023\u003d\u0076\u003b\u004a\u0025\u0068\u0062\u0062\u0043\u0020\u0076\u0062\u002a\u004c\u0069\u0050\u006e\u0069\u005f\u0035\u006a\u0075\u003b\u007b\u003b\u0064\u005d\u004a\u0039\u0059\u003c\u005e\u0029\u0023\u005e\u007a\u0066\u0039\u0031\u0076\u0038\u0038\u0032\u0059\u0068\u0032\u0045\u002a\u004a\u0072\u007d\u0038\u006f\u0035\u0024\u0069\u0036\u0069\u0051\u0079\u0076\u0038\u0057\u004d\u0047\u004f\u0021\u0032\u004e\u007d\u002f\u006a\u0052\u0052\u002f\u0022\u0038\u005e\u0048\u0060\u006c\u0066\u0038\u005a\u0067\u0034\u0077\u002b\u002a\u004b\u0060\u0066\u002c\u003a\u0029\u0066\u002d\u0024\u0048\u0074\u0030\u0044\u0076\u0040\u0055\u004e\u005f\u007b\u006f\u0031\u002b\u006d\u0042\u0075\u0042\u0042\u006a\u002d\u0039\u0023\u0060\u0025\u0047\u0068\u006a\u002b\u0034\u0063\u003a\u003d\u0074\u0027\u0065\u002f\u0068\u006b\u004e\u0033\u004c\u004f\u003e\u004a\u004d\u0039\u003e\u004d\u0020\u0060\u0029\u0061\u0074\u0071\u0037\u006b\u0063\u0026\u0021\u004b\u0061\u0022\u0067\u007c\u0048\u0038\u0054\u007b\u0057\u003c\u0033\u0035\u0074\u007e\u007a\u004c\u005a\u003a\u003e\u0050\u0042\u002b\u0046\u0066\u0049\u0040\u006e\u0043\u007c\u002f\u0041\u003c\u006e\u0052\u007d\u0041\u0050\u0070\u0065\u0069\u0046\u004a\u0048\u003e\u0071\u0047\u0022\u004e\u004b\u007a\u002a\u005c\u0044\u0063\u0030\u0023\u0061\u003b\u005f\u005d\u0054\u0067\u002b\u0066\u0053\u0060\u0027\u0028\u003d\u0078\u0034\u007c\u0063\u005e\u0045\u006f\u0021\u0033\u0071\u005b\u004b\u0046\u0022\u0039\u0078\u0065\u0029\u0052\u002f\u0031\u0030\u002b\u0035\u0065\u0055\u0067\u004a\u0043\u002a\u007b\u0020\u005a\u0079\u0045\u004c\u0068\u0049\u0031\u002b\u005e\u006d\u0078\u0041\u006f\u007d\u0036\u0035\u002b\u002d\u002c\u0038\u0051\u0067\u002a\u002e\u0065\u0063\u0024\u0024\u0058\u0065\u004c\u0068\u006f\u007c\u0069\u0055\u0065\u0071\u0049\u0079\u007b\u003c\u004f\u006d\u0062\u006d\u0060\u0029\u0031\u0054\u006c\u0059\u002c\u0038\u0023\u0038\u0052\u004b\u0026\u003f\u002b\u0054\u0053\u0071\u003b\u0069\u0048\u0071\u0048\u0043\u0078\u003b\u0050\u004a\u0033\u0065\u0031\u004a\u0044\u0041\u0053\u006b\u0051\u0039\u007c\u0071\u0031\u0028\u0048\u006a\u0055\u0050\u002c\u0047\u0032\u003e\u0060\u0025\u004a\u0029\u002b\u006a\u004b\u006c\u004d\u0039\u0020\u0065\u007a\u002d\u0035\u0053\u004d\u0078\u0076\u006f\u0043\u005d\u0057\u005c\u005f\u0059\u0078\u0055\u003a\u0074\u0044\u0067\u005d\u007e\u004d\u0067\u0048\u0052\u0025\u004c\u0032\u005c\u006c\u006a\u0055\u0067\u007d\u0037\u0057\u0049\u007b\u0033\u0077\u0035\u0023\u0060\u007b\u0039\u0067\u0041\u0049\u007d\u0028\u002a\u0057\u002e\u0057\u0062\u002d\u0062\u007e\u0078\u006f\u003e\u0061\u004f\u0055\u0057\u0070\u0062\u0038\u0042\u006c\u0040\u0063\u004a\u0023\u0053\u0036\u005b\u004a\u0065\u0024\u0043\u0079\u004a\u0020\u0059\u002e\u003a\u006a\u004a\u0070\u0078\u004d\u0058\u002f\u007c\u0028\u006f\u0071\u0077\u007d\u0077\u0046\u005d\u0068\u0064\u007c\u005d\u0067\u0036\u002c\u0051\u0051\u0043\u0037\u005e\u007a\u007a\u0043\u0046\u0047\u003c\u004e\u0077\u0063\u0053\u0057\u005d\u002a\u0037\u004a\u007a\u0073\u004b\u0066\u0032\u0055\u002d\u0073\u0071\u007d\u0054\u006b\u0054\u0026\u0066\u0058\u0022\u006f\u0042\u003b\u007c\u0075\u004a\u007b\u0030\u0045\u0036\u005f\u007b\u0063\u0077\u002c\u0052\u002a\u007d\u002a\u0074\u0030\u005a\u003e\u006f\u0075\u003b\u0069\u005c\u0050\u0064\u0022\u005c\u006d\u0023\u0047\u0062\u004c\u0057\u0071\u007a\u0023\u0046\u004a\u0040\u005c\u0069\u007b\u003b\u0066\u005d\u006c\u0074\u0079\u003c\u005b\u0049\u0062\u003b\u003c\u0059\u0039\u002c\u002c\u0062\u0029\u0029\u0061\u006c\u0052\u0047\u006d\u0070\u0052\u0021\u0046\u005c\u0053\u0035\u004d\u004e\u0078\u0064\u004a\u006c\u0052\u0037\u0027\u0033\u0073\u004c\u004b\u003f\u0068\u0054\u0061\u0034\u0078\u0052\u0064\u007a\u0061\u005b\u0059\u0033\u0042\u0046\u0052\u0030\u0078\u0051\u0036\u0079\u0071\u005c\u0048\u0028\u0022\u007d\u006b\u0053\u0024\u0043\u0065\u005c\u0071\u0065\u0067\u005f\u0036\u003f\u0027\u004b\u002d\u003c\u0048\u0043\u0058\u003b\u0077\u0052\u0043\u0075\u0037\u0041\u004d\u002d\u006f\u0072\u002a\u002e\u005a\u003d\u0072\u0047\u0068\u0042\u0034\u006d\u003a\u004e\u0044\u0029\u0025\u0052\u003f\u0024\u0042\u0048\u0030\u0079\u0069\u0041\u0023\u0028\u0031\u005a\u0029\u0025\u0043\u0061\u0076\u0038\u0055\u005d\u0026\u006a\u002f\u0034\u0037\u0058\u0028\u0031\u0027\u0045\u0076\u005a\u007b\u0071\u0040\u0032\u0021\u007e\u0068\u0026\u0054\u007c\u0077\u002c\u005b\u007e\u0057\u002b\u0057\u0049\u0063\u006a\u0078\u0048\u004a\u0054\u0066\u0067\u005b\u004b\u0058\u007a\u0067\u0024\u002c\u0073\u0031\u007a\u0062\u007a\u003c\u0024\u005a\u0046\u002f\u0064\u0049\u007e\u0052\u0076\u0068\u0058\u006b\u0056\u0052\u0037\u0068\u0047\u0075\u0056\u0028\u0046\u005e\u0022\u005a\u0070\u0027\u0050\u0040\u0076\u0079\u0060\u005a\u0041\u0057\u004b\u0026\u006a\u003a\u003f\u0060\u0057\u002f\u0030\u002b\u0021\u006d\u0045\u0058\u004b\u0070\u0033\u0040\u006d\u004c\u007b\u006f\u0029\u0057\u002c\u0037\u0069\u0048\u0028\u0077\u0074\u0021\u004d\u004d\u0041\u0062\u0027\u0067\u003f\u006c\u0074\u006f\u0078\u0073\u0045\u0045\u002f\u0027\u0072\u0062\u0052\u0029\u0026\u0066\u0020\u005f\u004c\u006b\u004d\u007a\u0059\u0041\u0061\u0053\u0034\u0028\u002e\u0028\u0048\u0060\u0035\u0076\u0024\u0057\u0035\u0028\u0066\u0054\u0045\u003f\u006e\u0058\u005a\u0037\u003a\u005d\u006d\u0068\u0025\u0061\u0027\u0028\u0029\u0073\u0068\u005c\u0049\u007b\u0027\u0027\u004e\u0039\u004b\u0044\u0077\u002f\u0048\u005b\u006b\u0045\u0041\u0070\u005d\u0048\u0048\u007d\u0033\u003d\u003e\u0034\u0067\u0058\u003c\u0031\u0041\u006d\u0029\u005a\u0061\u0060\u0074\u0046\u0064\u007a\u002e\u0076\u0032\u006d\u0065\u003f\u002b\u007d\u0023\u0035\u0027\u0048\u007e\u0073\u006f\u0034\u0027\u0036\u005c\u0020\u0027\u0049\u005d\u004f\u0062\u0023\u0041\u0052\u0035\u004d\u006d\u006a\u006e\u005f\u0025\u0060\u004e\u0056\u0028\u002e\u0057\u004d\u0065\u0069\u0037\u0029\u005f\u005b\u0074\u0029\u004b\u0034\u003d\u0043\u0073\u0042\u007b\u0033\u003f\u006c\u0064\u002c\u0063\u002a\u0068\u007a\u005a\u004d\u003e\u0029\u007b\u003a\u0023\u002c\u0041\u0066\u0048\u007d\u002c\u005a\u004d\u007c\u007a\u0066\u0058\u0047\u0025\u002c\u004f\u002e\u007d\u0066\u0033\u0070\u003f\u0041\u006b\u005c\u003c\u0055\u0070\u0070\u003d\u0074\u0050\u0027\u0051\u006a\u002a\u0078\u0072\u0028\u0075\u0031\u0069\u0030\u003f\u004b\u0040\u0025\u0021\u004a\u0057\u0068\u0034\u0063\u004b\u0070\u005c\u006b\u004a\u004d\u004e\u0038\u007a\u0048\u002c\u0076\u0040\u0066\u0078\u0051\u005b\u0040\u0029\u004b\u0041\u0060\u0075\u005e\u0020\u007d\u0026\u005c\u0078\u0040\u004e\u0051\u002b\u003a\u004f\u0037\u0027\u0072\u002c\u0054\u0078\u0031\u0041\u0039\u0032\u0022\u0064\u0067\u004f\u006c\u003c\u006a\u0051\u006b\u002a\u004e\u003a\u006f\u006a\u0070\u0039\u003c\u004f\u0048\u005e\u0065\u0075\u006f\u0041\u0035\u0037\u005c\u0030\u0021\u004c\u0056\u005b\u0029\u0051\u0043\u0047\u002d\u0033\u0022\u0025\u003f\u0061\u003c\u003d\u007e\u0075\u007a\u0058\u0050\u005a\u0028\u004f\u0065\u0049\u003d\u0067\u0076\u006a\u0048\u0037\u0068\u0065\u0026\u0047\u007d\u003e\u002a\u003d\u002c\u0030\u002f\u005f\u007d\u0032\u0038\u002b\u0075\u0079\u004a\u0079\u004a\u0026\u006e\u0033\u004b\u0038\u005d\u006c\u003b\u0074\u003e\u004b\u007d\u004b\u002c\u0041\u0047\u0024\u0069\u0030\u004a\u0026\u005d\u0020\u0047\u007c\u0046\u0045\u0038\u003d\u002b\u0074\u006f\u0075\u0038\u0035\u0020\u007d\u0057\u0021\u0029\u0054\u0074\u0055\u005c\u002b\u0074\u0051\u003e\u0026\u0062\u0068\u006d\u007d\u0074\u0074\u0039\u0034\u004f\u0077\u0074\u0052\u003d\u0061\u004b\u0054\u002d\u006f\u0075\u004a\u0034\u005e\u0036\u0024\u0059\u0021\u0027\u0035\u006a\u0024\u0047\u0034\u004b\u0059\u005a\u004f\u0054\u0023\u0066\u0030\u003f\u0058\u0040\u003c\u007e\u003e\u006d\u0061\u002f\u005e\u005d\u0049\u007d\u0021\u0044\u0051\u0047\u0024\u0030\u0022\u006b\u0068\u0046\u0032\u0072\u0063\u007e\u0075\u0030\u0059\u0074\u0054\u0062\u003c\u0071\u002f\u0073\u0021\u0048\u007d\u0058\u0025\u006a\u0035\u0020\u0062\u007d\u002a\u0071\u0033\u0024\u0067\u004a\u0021\u0068\u002d\u0038\u002f\u0061\u0071\u006c\u007b\u0039\u0027\u0038\u0036\u005e\u0046\u0068\u0062\u0048\u0067\u0076\u004e\u002e\u002d\u0023\u0030\u007c\u005b\u0067\u002e\u0020\u006e\u0020\u0077\u003d\u0048\u006d\u0039\u0047\u003c\u0051\u0073\u0050\u0071\u0032\u007e\u007d\u0062\u003f\u005f\u0025\u0025\u004e\u0032\u0048\u004d\u0021\u0026\u006a\u003b\u0051\u0064\u0050\u0060\u0079\u007d\u0032\u0065\u006f\u0056\u003c\u002d\u0062\u003c\u0046\u0022\u0032\u0024\u0064\u007e\u0067\u002e\u0060\u0027\u004a\u007c\u0072\u0051\u007e\u0067\u006e\u004f\u0058\u0045\u0036\u0051\u005b\u003e\u0074\u006c\u0039\u003a\u006d\u006c\u0059\u0020\u0071\u0043\u003f\u0076\u0060\u0051\u0067\u006c\u0055\u0029\u0032\u0033\u004f\u0030\u004e\u0025\u0068\u0066\u003e\u007a\u0059\u0042\u0038\u0069\u006a\u006b\u006e\u0034\u004f\u006e\u0066\u0068\u0029\u003c\u0056\u003c\u005f\u0023\u0036\u0029\u006a\u002b\u0073\u004f\u0059\u0066\u0047\u0051\u0045\u004c\u007b\u0049\u0058\u003c\u0062\u0035\u0038\u0072\u005e\u007c\u0031\u0020\u002f\u0072\u002d\u0034\u002b\u0071\u0042\u0034\u0078\u0072\u0073\u0049\u007a\u003b\u0045\u007c\u003a\u007d\u0058\u002a\u0028\u003f\u0029\u007e\u0038\u0032\u004a\u0061\u0054\u0040\u0065\u006c\u0040\u0027\u0073\u0065\u006c\u0064\u0078\u007d\u0074\u0032\u0062\u0063\u0044\u0067\u002e\u0056\u007e\u0059\u007d\u0066\u006b\u0048\u0068\u007c\u006c\u0059\u0039\u0044\u005d\u002e\u005f\u0020\u0063\u005d\u0062\u0032\u0024\u0037\u003d\u0029\u0067\u0035\u0063\u005c\u0069\u0078\u003e\u006f\u0026\u0047\u0026\u0050\u002e\u0030\u0062\u006e\u0045\u0049\u007a\u0053\u007e\u005b\u004d\u0039\u0036\u005e\u0058\u0048\u0042\u0064\u0067\u004f\u0045\u0027\u0061\u0046\u007b\u0027\u006f\u0061\u0049\u005d\u005e\u0039\u0075\u006c\u0046\u003b\u0022\u0033\u0033\u0057\u0050\u003a\u0042\u004c\u0076\u0025\u0054\u004e\u0042\u006f\u0061\u0048\u0027\u0030\u006d\u0052\u0022\u0046\u002f\u0034\u0054\u0071\u007e\u004c\u0052\u0032\u0072\u0056\u002b\u0039\u0050\u0036\u005e\u0058\u006c\u0044\u0025\u0029\u006f\u0076\u0029\u0061\u007e\u0027\u002f\u0024\u0043\u007c\u0070\u0067\u0077\u002d\u0050\u0031\u0071\u0020\u003a\u006e\u004d\u0044\u005a\u0067\u0042\u0038\u007c\u003f\u0043\u0073\u0053\u0029\u005d\u002a\u0044\u0052\u0044\u0070\u004d\u004d\u006c\u0072\u002f\u002c\u006c\u0073\u004f\u0037\u004d\u0061\u0037\u0027\u0048\u007c\u0059\u0037\u0072\u005d\u0048\u007c\u0030\u0079\u0032\u0024\u007d\u0029\u0063\u002f\u0031\u006a\u005a\u0066\u005a\u0049\u004e\u002c\u0028\u0040\u0067\u002d\u003b\u005f\u0041\u0058\u0052\u0043\u0061\u0074\u003c\u006f\u0027\u005a\u0022\u007d\u0073\u0056\u002b\u0054\u0037\u0039\u005c\u002b\u002d\u003d\u0020\u0053\u0032\u004e\u006a\u0022\u0026\u0036\u0032\u0054\u005b\u0035\u0061\u007a\u007b\u0037\u003b\u005c\u0060\u0071\u0035\u0072